      master.gain.setValueAtTime(0.2, ctx.currentTime);
      const src = ctx.createBufferSource(); src.buffer = brownBuf; src.loop = true;
      const lp = lpf(300); src.connect(lp); lp.connect(master); src.start(); nodes.push(src);
